  function display(size,density){const sizes=[...String(size).matchAll(/(Physical|Override) size:\s*(\d+)x(\d+)/gi)];const densities=[...String(density).matchAll(/(Physical|Override) density:\s*(\d+)/gi)];const s=sizes.at(-1),d=densities.at(-1);return {width:s?+s[2]:null,height:s?+s[3]:null,dpi:d?+d[2]:null,dp:s&&d?Math.round(Math.min(+s[2],+s[3])*160/(+d[2])):null,physicalSize:sizes[0]?`${sizes[0][2]}x${sizes[0][3]}`:null,physicalDpi:densities[0]?+densities[0][2]:null};}
  function focus(text){const lines=String(text).split(/\r?\n/);const preferred=lines.filter(x=>/mCurrentFocus|mFocusedApp|mResumedActivity|topResumedActivity/.test(x));for(const line of preferred){const m=line.match(/\b([\w]+(?:\.[\w]+)+)\/([\w.$]+)/);if(m)return {package:m[1],activity:m[2].startsWith('.')?m[1]+m[2]:m[2]};}return {package:'',activity:''};}
