  function argumentsOf(input){const tokens=[];let token='',quoteChar=null,started=false;for(let i=0;i<input.length;i++){const c=input[i];if(c==='\\'&&input[i+1]==='"'){token+='"';i++;started=true;}else if(quoteChar){if(c===quoteChar)quoteChar=null;else token+=c;started=true;}else if(c==='"'||c==="'"){quoteChar=c;started=true;}else if(/\s/.test(c)){if(started){tokens.push(token);token='';started=false;}}else{token+=c;started=true;}}if(quoteChar)throw new Error('命令中的引号未闭合');if(started)tokens.push(token);return tokens;}
  function settings(value){const s={...defaults};if(!value||typeof value!=='object')return s;for(const k of Object.keys(s)){if(typeof value[k]===typeof s[k])s[k]=value[k];}if(!pages[s.startPage])s.startPage='home';s.connectionMethod='usb';if(![80,85,90,95,100,105,110,115,120].includes(s.uiScale))s.uiScale=100;if(!['teal','indigo','bluegrey','green','purple'].includes(s.theme))s.theme='indigo';s.cpuInterval=Math.round(Math.max(500,Math.min(60000,s.cpuInterval)));if(!s.pushPath.startsWith('/')||/[\u0000\r\n]/.test(s.pushPath))s.pushPath='/sdcard/';if(!s.pushPath.endsWith('/'))s.pushPath+='/';return s;}
